// ===========================================================
// Nodo: Validar y Extraer Datos del Webhook de Calendly
// ===========================================================
// Extrae los campos relevantes del payload de Calendly y los
// transforma al formato necesario para HubSpot y Mailchimp.
//
// Campos esperados del webhook invitee.created de Calendly:
// - payload.invitee.name
// - payload.invitee.email
// - payload.event
// - payload.scheduled_event.start_time
// - payload.scheduled_event.end_time
// ===========================================================

const webhookData = $input.first().json;
const payload = webhookData.body?.payload ?? webhookData.payload;

if (!payload || !payload.invitee) {
  throw new Error(
    'Payload de Calendly inválido: no se encontró el campo "payload.invitee". ' +
    'Verifica que el webhook esté configurado para el evento invitee.created.'
  );
}

const invitee = payload.invitee;
const event = payload.scheduled_event ?? payload.event ?? {};

// Separar nombre completo en nombre y apellido
const fullName = (invitee.name || '').trim();
const nameParts = fullName.split(' ');
const firstName = nameParts[0] || '';
const lastName = nameParts.slice(1).join(' ') || '';

return [{
  json: {
    // Datos del lead
    email: invitee.email,
    firstName: firstName,
    lastName: lastName,
    fullName: fullName,
    // Datos de la cita
    eventStartTime: event.start_time || null,
    eventEndTime: event.end_time || null,
    eventType: event.name || event.event_type || 'Consulta',
    meetingUrl: event.location?.join_url || '',
    // Metadatos
    source: 'calendly',
    calendlyEventUri: event.uri || '',
    calendlyInviteeUri: invitee.uri || '',
    capturedAt: new Date().toISOString()
  }
}];

